@push('scripts')<script>document.addEventListener('change',async e=>{const input=e.target.closest('.return-receipt');if(!input)return;const form=input.closest('.return-refund-form'),message=form.querySelector('.return-scan-message'),reference=form.querySelector('.return-reference'),submit=form.querySelector('button[type="submit"]');reference.value='';submit.disabled=true;if(!input.files[0]){message.textContent='Select a receipt image to scan.';return;}message.textContent='Scanning receipt…';message.className='small mt-1 return-scan-message text-muted';const body=new FormData();body.append('receipt',input.files[0]);try{const response=await fetch(input.dataset.scanUrl,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||'','Accept':'application/json'},body});const data=await response.json();if(!response.ok||!data.ok){message.textContent=(data.errors||[data.error||'Receipt verification failed.']).join(' ');message.className='small mt-1 return-scan-message text-danger';return;}reference.value=data.reference_number||'';submit.disabled=!reference.value;message.textContent='Receipt verified. Reference number was scanned automatically.';message.className='small mt-1 return-scan-message text-success';}catch(_){message.textContent='Receipt scan is unavailable. Please try again.';message.className='small mt-1 return-scan-message text-danger';}});</script>@endpush
